"""Generates flashcards/month-02.csv (Anki import: Front, Back, Tags) for Days 31-63. Edit the list, then re-run.
Days 61-63 belong to Month 3 in SYLLABUS.md and are tagged m3."""
import csv, os
C = [
(31,"Ridge vs lasso penalty?","Ridge adds λΣw² (shrinks weights smoothly); lasso adds λΣ|w| (can set weights exactly to 0, so it selects features)."),
(31,"What is elastic net?","A mix of L1 and L2 penalties: sparsity like lasso, plus stability with correlated features like ridge."),
(31,"Why scale features before regularising?","The penalty treats all weights alike, so features on large scales would be penalised less, unfairly."),
(32,"What do polynomial features do?","They add powers and products of the inputs, so a linear model can fit curves; the degree controls flexibility."),
(32,"Signs of high variance in a validation curve?","Training error keeps falling while validation error rises as complexity grows."),
(33,"Why k-fold cross-validation?","Every row is used for validation once, giving a lower-variance estimate than a single split."),
(33,"Grid vs random search?","Random search samples the space and finds good values of the few important hyperparameters with fewer trials."),
(33,"What is nested CV for?","An unbiased estimate of a whole tuning procedure: the inner loop tunes, the outer loop evaluates."),
(34,"Softmax formula?","p_k = exp(z_k) / Σ_j exp(z_j); subtract max(z) first for numerical stability."),
(34,"Cross-entropy for one example?","−log p_true: the negative log probability assigned to the correct class."),
(34,"When are independent sigmoids right instead of softmax?","Multi-label problems, where classes are not mutually exclusive."),
(35,"Why touch the test set only once?","Every look lets choices adapt to it, and its estimate becomes optimistically biased."),
(36,"How does k-NN predict?","Find the k nearest training points and take their majority vote (or mean for regression)."),
(36,"Curse of dimensionality, in one line?","In many dimensions nearly all points are far apart and distances become similar, so 'nearest' carries little information."),
(36,"Why must k-NN inputs be scaled?","The distance is dominated by features with large numeric ranges."),
(37,"Naive Bayes assumption?","Features are conditionally independent given the class."),
(37,"Generative vs discriminative?","Generative models p(x|y)p(y) and uses Bayes' rule; discriminative models p(y|x) directly."),
(37,"Why Laplace smoothing in NB?","So that an unseen word/category does not give a zero probability that wipes out the product."),
(38,"What does an SVM maximise?","The margin: the distance from the boundary to the nearest training points (the support vectors)."),
(38,"Role of C in a soft-margin SVM?","Trade-off: large C punishes margin violations (less regularisation); small C allows more for a wider margin."),
(38,"What is the kernel trick?","Compute inner products in a high-dimensional feature space via a kernel function, without building the features."),
(39,"Gini impurity formula?","1 − Σ_k p_k²; 0 for a pure node, 0.5 for a 50/50 binary node."),
(39,"How does a tree choose a split?","It tries feature/threshold pairs and keeps the one with the largest impurity decrease (weighted by child sizes)."),
(39,"Why are unpruned trees high variance?","They grow until leaves are pure, memorising noise, so small data changes give very different trees."),
(40,"What is bagging?","Train models on bootstrap resamples and average them, which reduces variance."),
(40,"What extra trick makes a random forest?","Each split considers only a random subset of features, decorrelating the trees."),
(40,"What is out-of-bag error?","Error measured on the rows each tree did not see in its bootstrap sample: free validation."),
(41,"Gradient boosting in one line?","Add small trees one at a time, each fitted to the negative gradient (residuals for squared loss) of the current ensemble."),
(41,"Role of the learning rate in boosting?","It shrinks each tree's contribution; smaller rates need more trees but usually generalise better."),
(42,"Why put preprocessing in a Pipeline?","So that each CV fold fits imputation/scaling/encoding on its own training rows only (no leakage)."),
(43,"Permutation importance?","The drop in a validation score when one feature's values are shuffled."),
(43,"Weakness of impurity (MDI) importance?","It is computed on training data and can favour high-cardinality / continuous features (in our Day 43 run the random column still ranked last, so check, do not assume)."),
(43,"SHAP intuition?","Split a prediction into per-feature contributions that sum to (prediction − average prediction), by averaging over feature orderings."),
(44,"One-hot vs target encoding?","One-hot makes one column per category; target encoding replaces a category by its (smoothed, out-of-fold) mean target."),
(44,"Why must target encoding be out-of-fold?","Otherwise each row's own label leaks into its feature."),
(44,"Cyclical encoding of hour?","Use sin(2π·h/24) and cos(2π·h/24), so 23:00 and 00:00 are close."),
(45,"Why is accuracy misleading on imbalanced data?","Predicting the majority class scores high while catching no positives."),
(45,"Cost-optimal threshold for calibrated probabilities?","Predict positive when p > c_FP / (c_FP + c_FN)."),
(45,"PR-AUC vs ROC-AUC on rare positives?","PR-AUC focuses on the positive class and reflects precision; ROC-AUC can look good while precision is poor."),
(46,"What is data leakage?","Information from validation/test (or the future, or the label) reaching training, inflating scores."),
(46,"How to address a nested parameter in a Pipeline?","step__param, e.g. clf__C or prep__cat__onehot__min_frequency."),
(46,"What does handle_unknown='ignore' do?","Encodes a category unseen in training as all zeros instead of raising an error."),
(47,"k-means objective?","Minimise inertia: the sum of squared distances from each point to its assigned centroid."),
(47,"Two steps of Lloyd's algorithm?","Assign each point to the nearest centroid; move each centroid to the mean of its points. Repeat."),
(47,"Why k-means++ and several inits?","k-means finds local minima; spread-out seeding and multiple restarts give better solutions."),
(48,"What does DBSCAN need and give?","eps and min_samples; it finds arbitrarily shaped dense clusters and labels sparse points as noise."),
(48,"GMM vs k-means?","A GMM gives soft memberships and elliptical clusters with their own covariances, fitted by EM."),
(48,"E and M steps of EM for a GMM?","E: compute each point's responsibility for each component. M: re-estimate weights, means and covariances from them."),
(49,"Silhouette value for a point?","(b − a)/max(a, b): a = mean distance within its cluster, b = to the nearest other cluster."),
(49,"Why validate segments beyond internal scores?","Internal scores can disagree and prefer different k; usefulness to the people acting on segments matters."),
(50,"How do you get PCA from the SVD?","Centre X; Xc = UΣVᵀ. Components are rows of Vᵀ; variance of component j is σ_j²/(m−1)."),
(50,"PCA reconstruction MSE equals?","The sum of the dropped eigenvalues divided by the number of features (checked exactly on digits)."),
(50,"What do t-SNE plots NOT preserve?","Between-cluster distances, cluster sizes and axis meaning; only local neighbourhoods."),
(50,"Digits: components for 90% variance?","21 of 64 (our run)."),
(51,"Density-based anomaly recipe?","Fit p(x) on normal data; flag p(x) < ε; choose ε on a labelled validation set (e.g. best F1)."),
(51,"Why did the multivariate Gaussian win on Day 51?","The features are strongly correlated; only the full covariance models that (test F1 0.872 vs 0.703 independent)."),
(51,"Isolation Forest intuition?","Anomalies are isolated by random splits in fewer steps (shorter average path length)."),
(52,"Biased matrix factorisation prediction?","r̂ = μ + b_u + b_i + p_u·q_i."),
(52,"Why fit MF on observed ratings only?","Missing is not zero; filling with zeros biases predictions towards dislike."),
(52,"What did unregularised MF do on MovieLens?","Overfit: test RMSE 0.9524 at epoch 10 rose to 1.0173 at epoch 30; λ=0.05 reached 0.9348."),
(52,"Cold start?","New users/items have no ratings, so collaborative filtering has nothing to use; fall back to biases or content features."),
(53,"Leaky vs safe rolling feature?","y.rolling(24).mean() includes y_t (leaky); y.shift(1).rolling(24).mean() uses only the past."),
(53,"Why is shuffled CV wrong for time series?","Neighbouring hours land in train and validation, so the model interpolates (bike MAE 26.5 shuffled vs 48.7 time-split)."),
(53,"Which naive baselines should a forecast beat?","'Same as last step' and 'same time last season' (e.g. same hour last week)."),
(54,"What is calibration?","Among cases predicted p, a fraction p are positive."),
(54,"Platt vs isotonic calibration?","Platt (sigmoid, 2 parameters) for small data; isotonic (monotone steps) for more data and arbitrary distortion."),
(54,"Does calibration change ROC-AUC?","No: it is a monotone map, so the ranking is unchanged; Brier and log loss improve."),
(54,"What does a partial dependence plot show?","The model's average prediction as one feature is set to each grid value for all rows."),
(55,"Avoidable bias and variance (Ng style)?","Avoidable bias ≈ train error − reference error; variance ≈ dev error − train error."),
(55,"High-bias learning curve?","Train and validation error converge to a high plateau; more data won't help."),
(55,"Error analysis method?","Tally misclassified dev examples by category/slice; fix the categories that hold the most errors."),
(56,"Why can ||x||² be dropped in k-means assignment?","It is the same for every centroid, so argmin_j(||c_j||² − 2x·c_j) gives the same label."),
(56,"Where did Rust's k-means speed-up come from?","Mostly parallelism (rayon): serial Rust was slower than NumPy's BLAS matmul trick."),
(56,"Benchmark hygiene rules?","Same inputs and init, best-of-N timing, verify identical outputs, state the machine, include the strongest baseline, release builds."),
(57,"Sources of non-determinism in ML runs?","Seeds (splits, init, shuffles), data changes, library versions, threading/float order."),
(57,"How to verify model persistence?","Reload the saved pipeline (ideally in a fresh process) and assert predictions are identical."),
(57,"Why report seed spread?","Differences smaller than the spread (std 0.0008 AUC on adult) are not evidence that one model is better."),
(58,"Capstone rule for the test set?","Split it off first; all choices from CV on train; evaluate once."),
(58,"Why choose the threshold on out-of-fold predictions?","Predictions on rows the model trained on are overconfident."),
(59,"Bootstrap CI recipe?","Resample test rows with replacement, recompute the metric many times, take the 2.5th and 97.5th percentiles."),
(59,"Demographic parity, equal opportunity, predictive parity?","Equal predicted-positive rates; equal recall; equal precision across groups."),
(59,"Why show n in slice tables?","Small groups give very noisy estimates; n tells the reader how much to trust each row."),
(60,"What makes a capstone reproducible?","One command regenerates the same numbers from code, config and a fingerprinted dataset, documented in a model card."),
(61,"Perceptron update rule?","On a mistake (labels ±1): w += y·x, b += y."),
(61,"When does the perceptron converge?","When the data are linearly separable (mistakes bounded by (R/γ)²)."),
(61,"Maximum of the sigmoid derivative?","0.25, at z = 0."),
(62,"Why do networks need non-linear activations?","Without them stacked layers collapse into one linear map."),
(62,"He initialisation?","Weights with variance 2/n_in, keeping ReLU activation variance roughly constant across layers."),
(62,"Parameter count for 64→32→10?","64·32 + 32 + 32·10 + 10 = 2410."),
(63,"Gradient of softmax + cross-entropy w.r.t. logits?","dZ = (P − Y)/m."),
(63,"Gradient-check pass criterion?","Relative error ||num − ana|| / (||num|| + ||ana||) below about 1e-7 with central differences."),
(63,"Where does the ReLU mask enter backprop?","dZ1 = dA1 ⊙ [Z1 > 0]."),
]
p = os.path.join(os.path.dirname(__file__), "month-02.csv")
with open(p, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    for d, q, a in C: w.writerow([q, a, f"{'m3' if d > 60 else 'm2'} d{d}"])
print(len(C), "cards ->", p)
